// Package dep is what lib imports.
package dep

// Context is done when its channel closes.
type Context interface{ Done() <-chan struct{} }

// Option configures a Base.
type Option func(*Base)

// Base is embedded by lib.Tagged.
type Base struct{ ID int }

// Default is a Base.
var Default = Base{}

