// Package lib is a library whose import path's last element holds a dot,
// which an id writes %2e.
package lib

import "example.com/rt/dep"

// Pair is a generic struct; its unexported field is no part of its API.
type Pair[K comparable, V any] struct {
	// Key is the key.
	Key K `json:"key"`
	Val V // Val is the value.
	hidden int
}

// Get reads through a pointer receiver.
func (p *Pair[K, V]) Get(k K) (V, bool) {
	var zero V
	return zero, false
}

// Len reads through a value receiver.
func (p Pair[K, V]) Len() int { return 0 }

// New is a generic function with a variadic parameter.
func New[K comparable, V any](k K, v V, opts ...dep.Option) *Pair[K, V] { return nil }

// Both declares its type parameters grouped.
func Both[A, B any](a A, b B) {}

// Ordered is a constraint.
type Ordered interface{ ~int | ~string }

// Max declares two type parameters with one named constraint.
func Max[A Ordered, B Ordered](a A, b B) A { return a }

// Sealed has an unexported method: only this package implements it.
type Sealed interface {
	// Do does.
	Do(ctx dep.Context) error
	seal()
}

// Reader embeds Sealed.
type Reader interface {
	Sealed
	Read() []byte
}

// Tagged has a tag on grouped names, an embedded field and an unexported one.
type Tagged struct {
	dep.Base
	A, B string `json:"ab,omitempty"`
	c    int
}

// Code is a defined type with a method.
type Code uint32

// String names a code.
func (c Code) String() string { return "" }

// The constants of the package.
const (
	// First is typed.
	First Code = 1
	Untyped = 2.5
	Text = "x"
)

// Default is a variable whose type is inferred from another package's.
var Default = dep.Default

// Hook is a function-typed variable.
var Hook func(error) bool

// Handler is a func type naming a generic instance.
type Handler func(ctx dep.Context, p *Pair[string, int]) error

type hidden struct{}

// Exported is a method of an unexported type: no API.
func (hidden) Exported() {}

