// Package facade re-exports lib under its own names, as pkg/v1 does.
package facade

import (
	d "example.com/rt/dep"
	lib "example.com/rt/lib.v2"
)

// Pair aliases a generic type.
type Pair[K comparable, V any] = lib.Pair[K, V]

// Code aliases a defined type.
type Code = lib.Code

// Ctx aliases another package's interface, imported under another name.
type Ctx = d.Context

// Bytes aliases an unnamed type: it has no owner.
type Bytes = []byte

// First re-exports a constant.
const First = lib.First

// New forwards to lib.New.
func New(k string, v int) *Pair[string, int] { return lib.New(k, v) }
